async function handleAction(name, button) {
  if (views[name]) { location.hash = name; if (state.view === name) await changeView(name); return; }
  if (name === 'table-page') { const entry = state.tables[button.dataset.tableId]; if (entry) { entry.prefs.page += Number(button.dataset.delta); updateTable(entry.id); } return; }
  if (name === 'playback') { togglePlayback(); return; }
  if (name === 'new-run') { configureRunDefaults(); populateSeriesControls(); openDialog('#run-dialog'); return; }
  if (name === 'filter-decisions' || name === 'filter-safety') { state.eventFilter = name === 'filter-safety' ? 'safety' : 'decisions'; render(); return; }
  if (name === 'add-asset') { openAsset(); return; }
  if (name === 'edit-asset') { openAsset(state.assets.find(asset => String(asset.id) === button.dataset.id)); return; }
  try {
    await busyButton(button, async () => {
      if (name === 'import-karnataka') { const result = await api('/ingestion/karnataka', { method: 'POST' }); toast(`Import finished: ${number(result.inserted, 0)} new observations · ${number(result.duplicates, 0)} duplicates skipped.`); await refreshAll(); }
      if (name === 'train-model') { const input = seriesInput(); const target = /solar/i.test(input.metric) ? 'solar' : /wind/i.test(input.metric) ? 'wind' : 'demand'; const result = await api('/forecasts/train', { method: 'POST', body: JSON.stringify({ target, ...input }) }); state.selectedModel = result.id; toast(`Series trained. Validation champion: ${result.algorithm || result.name}.`); await refreshAll(); }
      if (name === 'generate-forecast') { if (!chosenModel()) throw new Error('Select a compatible registered model first.'); await api('/forecasts/generate', { method: 'POST', body: JSON.stringify({ model_id: state.selectedModel, horizon: 14 }) }); toast('Forecasts generated and saved for the selected model version.'); await loadViewData(); render(); }
      if (['pause-run', 'resume-run', 'cancel-run'].includes(name)) { const operation = name.split('-')[0]; await api(`/runs/${encodeURIComponent(state.selectedRun)}/${operation}`, { method: 'POST' }); toast(`${human(operation)} requested for the selected run.`); await refreshAll(); }
      if (name === 'export-json' || name === 'export-csv') { if (!state.selectedRun) throw new Error('Select a simulation run first.'); await downloadExport(`/runs/${encodeURIComponent(state.selectedRun)}/export?format=${name === 'export-json' ? 'json' : 'csv'}`); }
      if (name === 'export-comparison') { const id = selected()?.comparison_id; if (!id) throw new Error('This run has no saved comparison.'); await downloadExport(`/comparisons/${encodeURIComponent(id)}/export`); }
      if (name === 'delete-asset') { await api(`/assets/${encodeURIComponent(button.dataset.id)}`, { method: 'DELETE' }); state.assets = await api('/assets'); toast('Asset deleted.'); render(); }
    });
  } catch (error) { report(error); }
}
