document.addEventListener('click', event => { if (!event.target.closest('.export-menu')) document.querySelectorAll('.export-menu[open]').forEach(menu => { menu.open = false; }); if (!event.target.closest('.sidebar') && !event.target.closest('#mobile-menu')) { $('.sidebar').classList.remove('open'); $('#mobile-menu').setAttribute('aria-expanded', 'false'); } });
