  if (['forecast-model-select', 'run-model-select'].includes(id)) { state.selectedModel = event.target.value; populateModelControls(); if (id === 'forecast-model-select') { $('#global-error').hidden = true; try { await loadViewData(); render(); } catch (error) { report(error); } } return; }
