  try { await busyButton($('button[type=submit]', form), async () => { const data = new FormData(form), scenario = {}; for (const name of ['steps', 'step_hours', 'battery_capacity_kwh', 'initial_soc', 'grid_import_limit_kw', 'solar_capacity_kw', 'base_load_kw', 'seed', 'replay_speed']) if (!assetDefaultFields.includes(name) || form.elements[name].dataset.override === 'true') scenario[name] = Number(data.get(name)); scenario.name = String(data.get('name')); const mode = data.get('mode'), input = mode === 'historical' ? { ...seriesInput(), model_id: state.selectedModel || null } : {}; const result = await api('/runs', { method: 'POST', body: JSON.stringify({ scenario, compare: data.has('compare'), mode, ...input }) }); const runs = result.runs || []; stopPlayback(); state.frameIndex = null; state.explicitRun = true; state.selectedRun = (runs.find(run => !/baseline/i.test(run.policy || '')) || runs[0])?.id || state.selectedRun; $('#run-dialog').close(); toast(mode === 'historical' ? 'Simulation started with the selected input series and saved configuration.' : 'Simulation started using the configured live feed and saved configuration.'); await refreshAll(); }); } catch (error) { errorBox.textContent = error.message; errorBox.hidden = false; }
